POLICY = [  # (역할, 세그먼트) 허용 표. 표에 없으면 거부
    ("payments-dev", "payments-admin"),
    ("security", "payments-admin"),
    ("all", "wiki"),
]
def decide(user, device, segment):
    roles = set(user["roles"]) | {"all"}
    if not any(r in roles and s == segment for r, s in POLICY):
        return "deny: 역할 없음"
    if not device["managed"]:
        return "deny: 회사 기기 아님"
    if device["os_patch_days"] > 30:
        return "deny: OS 업데이트 30일 넘음"
    return "allow"

kim = {"name": "kim", "roles": ["payments-dev"]}
lee = {"name": "lee", "roles": ["marketing"]}
ok, old = {"managed": True, "os_patch_days": 3}, {"managed": True, "os_patch_days": 45}
for u, d, s in [(kim, ok, "payments-admin"), (lee, ok, "payments-admin"),
                (kim, old, "payments-admin"), (lee, ok, "wiki")]:
    print(u["name"], s, "->", decide(u, d, s))
# kim payments-admin -> allow
# lee payments-admin -> deny: 역할 없음
# kim payments-admin -> deny: OS 업데이트 30일 넘음
# lee wiki -> allow
